const listRSSSubscriptions = `-- name: ListRSSSubscriptions :many
SELECT
    subscription.id, subscription.series_id, subscription.mapping_profile_id, subscription.name, subscription.feed_url, subscription.enabled, subscription.poll_interval_seconds, subscription.last_polled_at, subscription.next_poll_at, subscription.version, subscription.created_at, subscription.updated_at, subscription.source_season, subscription.deleted_at, subscription.auto_review, subscription.cleanup_source_on_completion, subscription.completed_at, subscription.include_keywords, subscription.exclude_keywords, subscription.auto_episode_mapping,
    series.title AS series_title,
    series.tmdb_series_id,
    (
        SELECT count(*)
        FROM episode_tasks AS task
        JOIN acquisitions AS acquisition ON acquisition.id = task.acquisition_id
        JOIN rss_entries AS entry ON entry.id = acquisition.rss_entry_id
        WHERE entry.subscription_id = subscription.id
          AND task.state = 'failed'
    ) AS retryable_task_count
FROM rss_subscriptions AS subscription
JOIN media_series AS series ON series.id = subscription.series_id
WHERE subscription.deleted_at IS NULL
  AND (
      $1::text IS NULL
      OR strpos(LOWER(subscription.name), LOWER($1::text)) > 0
      OR strpos(LOWER(series.title), LOWER($1::text)) > 0
  )
  AND (
      $2::uuid IS NULL
      OR (
          COALESCE($3::text, 'newest') = 'oldest'
          AND (subscription.created_at, subscription.id) > (
              SELECT cursor.created_at, cursor.id
              FROM rss_subscriptions AS cursor
              WHERE cursor.id = $2
          )
      )
      OR (
          COALESCE($3::text, 'newest') = 'newest'
          AND (subscription.created_at, subscription.id) < (
              SELECT cursor.created_at, cursor.id
              FROM rss_subscriptions AS cursor
              WHERE cursor.id = $2
          )
      )
  )
ORDER BY
    CASE WHEN COALESCE($3::text, 'newest') = 'oldest' THEN subscription.created_at END ASC,
    CASE WHEN COALESCE($3::text, 'newest') = 'newest' THEN subscription.created_at END DESC,
    CASE WHEN COALESCE($3::text, 'newest') = 'oldest' THEN subscription.id END ASC,
    CASE WHEN COALESCE($3::text, 'newest') = 'newest' THEN subscription.id END DESC
LIMIT $4
`

